# Cursor row for the topic-model projection (ADR-051). The model itself is
# the `Topic` table, written through by the projection; this row only
# records how far the fold has applied the event log.
#
# id:: KSUID (`topicmodel_…`), generated by the repository on first upsert.
# occurredAt:: Business time of the latest applied event.
# acceptedAt:: Event-log acceptance time. Together with lastEventId this is the cursor.
class TopicModelProjection < ApplicationRecord
  self.table_name = "TopicModelProjection"

  validates :projectId, presence: true, uniqueness: true
  validates :projectId, uniqueness: true
  validates :createdAt, presence: true
  validates :updatedAt, presence: true
  validates :occurredAt, presence: true
  validates :acceptedAt, presence: true
  validates :lastEventId, presence: true
  validates :projectionVersion, presence: true
end
